window.onload=function(){const swiper=new Swiper('.card ',{slidesPerView:1,speed:800,effect:'fade',fadeEffect:{crossFade:!0,},direction:'horizontal',loop:!0,navigation:{nextEl:'.swiper-button-next',prevEl:'.swiper-button-prev',},});const switchers=document.querySelectorAll('.switcher');switchers.forEach((switcher)=>{switcher.addEventListener('click',()=>{switcher.classList.toggle('active');switcher.parentElement.parentElement.classList.toggle('hidden')})})}